SELECT id, correlation_id, symbol, interval_code, candle_open_time, observed_at, stage, started_at, finished_at, elapsed_ms, outcome, thread_name FROM fix129_stage_timing WHERE started_at BETWEEN '2026-10-11 20:54:00' AND '2026-10-12 10:06:00' AND (symbol IN ('ACEUSDT','SHIBUSDT','DOGEUSDT','XRPUSDT','EGLDUSDT') OR started_at BETWEEN '2026-10-11 21:00:00' AND '2026-10-11 21:00:10' OR started_at BETWEEN '2026-10-11 22:43:25' AND '2026-10-11 22:43:36' OR started_at BETWEEN '2026-10-12 10:05:00' AND '2026-10-12 10:05:19') ORDER BY started_at LIMIT 300